pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public {
        c = new C();
        owner = address(0xA11CE);
        vm.prank(owner);
        c.initialize();
    }

    function testFuzz_property(address newImpl) public {
        vm.assume(newImpl != owner);
        bool ok;
        vm.prank(owner);
        try c.updateRoundImplementation(payable(newImpl)) {
            ok = true;
        } catch {
            ok = false;
        }
        // Rule: roundImplementation is always set to a non-zero address that
        // equals the requested value whenever the call succeeds; zero address
        // is always rejected.
        assertTrue(
            (ok && c.roundImplementation() == newImpl && newImpl != address(0)) ||
            (!ok && c.roundImplementation() == address(0)),
            "roundImplementation must be a non-zero requested address or the call must revert"
        );
    }
}

