import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        c.initialize(); // this contract becomes the owner
    }

    function testFuzz_property(address impl) public {
        // Admissible domain: the entire address space, including address(0).
        bool ok;
        vm.prank(address(this)); // owner call
        try c.updateRoundImplementation(payable(impl)) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: updateRoundImplementation(x) succeeds if and only if
        // x != address(0), and on success roundImplementation() == x.
        if (impl != address(0)) {
            assertTrue(ok && c.roundImplementation() == impl);
        } else {
            assertTrue(!ok);
        }
    }
}

