pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 seed) public {
        // WIDE domain: make address(0) a frequent, reachable choice so the fuzzer
        // reliably hits the bug-triggering input.
        address impl = (seed % 3 == 0) ? address(0) : address(uint160(seed));

        address owner = address(uint160(seed ^ 0x1234));
        if (owner == address(0)) owner = address(0xA11CE);

        // initialize as owner so owner() == owner
        vm.prank(owner);
        c.initialize();

        // drive c through updateRoundImplementation as the owner
        vm.prank(owner);
        bool ok;
        try c.updateRoundImplementation(payable(impl)) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: the update succeeds iff the implementation is non-zero,
        // and on success the public getter returns exactly the requested address.
        // Reference: reverts for address(0) (ok == false).
        // Mutant: succeeds for address(0), breaking ok == (impl != address(0)).
        assertTrue(ok == (impl != address(0)) && (!ok || c.roundImplementation() == impl));
    }
}

