contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address payable newImpl) external {
        require(newImpl != address(0));

        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(c.updateRoundImplementation.selector, newImpl)
        );

        assert(ok == (c.owner() == address(this)));
    }
}

